function hashString(s){let h=2166136261;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0).toString(36)}
function splitBilingual(s){const parts=String(s||'').split(' / ');return parts.length>1?{ar:parts[0].trim(),en:parts.slice(1).join(' / ').trim()}:{ar:String(s||'').trim(),en:String(s||'').trim()}}
function defaultCategoryId(type,value){if(!value)return'';const raw=String(value).trim();const defs=type==='activities'?DEFAULT_ACTIVITIES:DEFAULT_GOODS;const aliases=LEGACY_DEFAULT_ALIASES[type]||{};if(aliases[raw])return aliases[raw];const low=raw.toLowerCase();for(const [id,ar,en] of defs){const options=[id,ar,en,`${ar} / ${en}`,`${en} / ${ar}`].map(x=>String(x).trim().toLowerCase());if(options.includes(low))return id;}return''}
function normalizeLegacyCategory(type,value,customMap){const raw=String(value||'').trim();if(!raw)return'';const known=defaultCategoryId(type,raw);if(known)return known;const map=customMap[type];if(map.has(raw))return map.get(raw);const id=`legacy_${type}_${hashString(raw)}`;map.set(raw,id);const {ar,en}=splitBilingual(raw);state[type].push({id,name:ar||raw,ar:ar||raw,en:en||ar||raw,_updatedAt:Date.now(),_deleted:false});return id}
function migrateLegacy(source){const old=source||{},stamp=Date.now();state=blankState();state.catalog=Array.isArray(old.catalog)?old.catalog.filter(x=>x&&typeof x==='object').map(x=>({...x,id:String(x.id??uid('catalog')),_updatedAt:num(x._updatedAt)||stamp,_deleted:!!x._deleted})):[];state.prefs={currency:String(old.cur||old.currency||'د.م.'),language:old.language==='en'?'en':'ar',shop:{name:old.shopInfo?.name||old.shop?.name||'',phone:old.shopInfo?.phone||old.shop?.phone||'',address:old.shopInfo?.address||old.shop?.address||''},_updatedAt:stamp};const sector=old.sectorData&&typeof old.sectorData==='object'?old.sectorData:{};const customMap={activities:new Map(),goods:new Map()};for(const type of ['activities','goods']){for(const item of Array.isArray(sector[type])?sector[type]:[]){if(typeof item==='string'&&item.trim())normalizeLegacyCategory(type,item,customMap)}}
 const animals=Array.isArray(sector.animals)?sector.animals:[];state.animals=animals.filter(x=>x&&typeof x==='object').map(x=>({...x,id:String(x.id??uid('animal')),_updatedAt:num(x._updatedAt)||stamp,_deleted:!!x._deleted,species:normalizeSpecies(x.species)}));
 state.lands=(Array.isArray(sector.lands)?sector.lands:[]).filter(x=>x&&typeof x==='object').map(x=>({...x,id:String(x.id??uid('land')),_updatedAt:num(x._updatedAt)||stamp,_deleted:!!x._deleted,role:normalizeLandRole(x.role)}));
 state.events=(Array.isArray(sector.events)?sector.events:[]).filter(x=>x&&typeof x==='object').map(x=>({...x,id:String(x.id??uid('event')),_updatedAt:num(x._updatedAt)||stamp,_deleted:!!x._deleted,animalId:String(x.animalId??''),cost:x.cost===undefined?'':x.cost,type:normalizeCareType(x.type)}));
 const rows=Array.isArray(old.records)?old.records:[];state.records=rows.filter(r=>r&&typeof r==='object').map((r,i)=>{const x={...r,id:String(r.id??uid('legacy')),ref:r.ref||`REC-${100+i}`,date:r.date||today(),time:r.time||'12:00',method:r.method||'نقداً',payments:Array.isArray(r.payments)?r.payments.map(p=>({...p,amount:num(p.amount??p.amt),amt:num(p.amt??p.amount)})):[],_updatedAt:num(r._updatedAt)||stamp,_deleted:!!r._deleted};if(['buy','deal'].includes(x.kind)){x.kind=x.kind||'buy';x.purchase=num(x.purchase??x.buy);x.sale=num(x.sale??x.sell);x.expenses=num(x.expenses??x.exp);x.received=num(x.received??x.recv);x.supplier=x.supplier||x.sn||'';x.supplierPhone=x.supplierPhone||x.sp||'';x.customer=x.customer||x.cn||'';x.customerPhone=x.customerPhone||x.cp||'';x.activity=normalizeLegacyCategory('activities',x.activity,customMap);x.goodType=normalizeLegacyCategory('goods',x.goodType,customMap);}else if(['rep','repair'].includes(x.kind)){x.kind=x.kind==='rep'?'rep':'repair';x.charge=num(x.charge??x.price);x.received=num(x.received??x.recv);x.labor=num(x.labor??x.pay);x.customer=x.customer||x.cn||'';x.customerPhone=x.customerPhone||x.cp||'';x.activity=normalizeLegacyCategory('activities',x.activity,customMap);}else if(x.kind==='debt'){x.direction=x.direction||((x.debtType==='owe'||x.debtType==='payable')?'payable':'receivable');x.total=num(x.total);x.paid=num(x.paid);x.person=x.person||x.name||'';}else if(['vch','voucher'].includes(x.kind)){x.direction=x.direction||((x.vtype==='inc'||x.direction==='income')?'income':'expense');x.amount=num(x.amount??x.amt);x.category=x.category||x.cat||'';x.party=x.party||x.person||'';}return x;});
 for(const type of ['activities','goods']){const arr=Array.isArray(sector[type])?sector[type]:[];for(const item of arr)if(typeof item==='string'&&item.trim())normalizeLegacyCategory(type,item,customMap)}return state;}
function normalizeSpecies(value){const s=String(value||'').toLowerCase();if(['cattle','بقر','أبقار'].includes(s))return'cattle';if(s.includes('sheep')||s.includes('غنم'))return'sheep';if(s.includes('goat')||s.includes('ماعز'))return'goat';if(s.includes('camel')||s.includes('إبل'))return'camel';if(s.includes('hen')||s.includes('دجاجة'))return'hen';if(s.includes('rooster')||s.includes('ديك'))return'rooster';return['cattle','rooster','hen','sheep','goat','camel','other'].includes(s)?s:'other'}
function normalizeLandRole(value){const s=String(value||'').toLowerCase();if(s.includes('tenant')||s.includes('مكتري'))return'tenant';if(s.includes('landlord')||s.includes('مؤجر'))return'landlord';if(s.includes('own')||s.includes('ذاتي'))return'own';return'other'}
function normalizeCareType(value){const s=String(value||'').toLowerCase();if(s.includes('feed')||s.includes('تغذ'))return'feed';if(s.includes('treat')||s.includes('علاج'))return'treatment';if(s.includes('vacc')||s.includes('تلقيح'))return'vaccine';if(s.includes('weight')||s.includes('وزن'))return'weight';if(s.includes('birth')||s.includes('ولادة'))return'birth';return['feed','treatment','vaccine','weight','birth','other'].includes(s)?s:'other'}
function normalizeImportedState(obj){if(!obj||typeof obj!=='object')throw new Error(tr('النسخة المشفرة غير صالحة'));if(obj.format==='merchant-ledger-encrypted')throw new Error(tr('النسخة المشفرة غير صالحة'));if(obj.data&&typeof obj.data==='object'&&Array.isArray(obj.data.records)){const src=obj.data;const out=blankState();for(const k of COLLECTIONS)out[k]=Array.isArray(src[k])?src[k].filter(x=>x&&typeof x==='object'&&x.id!=null).map(x=>({...x,id:String(x.id),_updatedAt:num(x._updatedAt)||Date.now(),_deleted:!!x._deleted})):[];out.prefs={...blankState().prefs,...(src.prefs||{}),shop:{...blankState().prefs.shop,...(src.prefs?.shop||{})}};return out}if(obj.schema===1&&Array.isArray(obj.records)){const out=blankState();for(const k of COLLECTIONS)out[k]=Array.isArray(obj[k])?obj[k].filter(x=>x&&typeof x==='object'&&x.id!=null).map(x=>({...x,id:String(x.id),_updatedAt:num(x._updatedAt)||Date.now(),_deleted:!!x._deleted})):[];out.prefs={...out.prefs,...(obj.prefs||{}),shop:{...out.prefs.shop,...(obj.prefs?.shop||{})}};return out}if(Array.isArray(obj.records)){const previous=state;try{return migrateLegacy(obj)}finally{state=previous}}throw new Error(tr('لا توجد بيانات صالحة للاستيراد'))}
function summaryBy(key){const groups=new Map();for(const r of recordsLive()){if(key==='activity'&&!['deal','buy','repair','rep'].includes(r.kind))continue;if(key==='goodType'&&!['deal','buy'].includes(r.kind))continue;const raw=r[key]||'unclassified';const g=groups.get(raw)||{key:raw,count:0,sales:0,profit:0};g.count++;if(['deal','buy'].includes(r.kind)){g.sales+=num(r.sale??r.sell);g.profit+=num(r.sale??r.sell)-num(r.purchase??r.buy)-num(r.expenses??r.exp)}else if(['repair','rep'].includes(r.kind)){g.sales+=num(r.charge??r.price);g.profit+=num(r.charge??r.price)-num(r.parts)-num(r.labor??r.pay)}groups.set(raw,g)}return[...groups.values()].sort((a,b)=>b.profit-a.profit)}
function renderDashboard(){const all=recordsLive();const now=new Date();const periodRows=all.filter(r=>{if(dashPeriod==='all')return true;const d=new Date((r.date||today())+'T12:00:00');if(Number.isNaN(d.getTime()))return true;if(dashPeriod==='today')return(r.date||'')===today();if(dashPeriod==='year')return d.getFullYear()===now.getFullYear();if(dashPeriod==='week')return(now-d)<=7*86400000&&d<=now;return d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth()});const deals=periodRows.filter(r=>['deal','buy'].includes(r.kind)),repairs=periodRows.filter(r=>['repair','rep'].includes(r.kind)),vouchers=periodRows.filter(r=>['voucher','vch'].includes(r.kind));const revenue=deals.reduce((s,r)=>s+num(r.sale??r.sell),0)+repairs.reduce((s,r)=>s+num(r.charge??r.price),0)+vouchers.filter(r=>r.direction==='income'||r.vtype==='inc').reduce((s,r)=>s+num(r.amount??r.amt),0);const costs=deals.reduce((s,r)=>s+num(r.purchase??r.buy)+num(r.expenses??r.exp),0)+repairs.reduce((s,r)=>s+num(r.parts)+num(r.labor??r.pay),0)+vouchers.filter(r=>r.direction==='expense'||r.vtype==='exp').reduce((s,r)=>s+num(r.amount??r.amt),0);const profit=revenue-costs;const debts=getDebtItems();const rec=debts.filter(x=>x.direction==='receivable').reduce((s,x)=>s+x.remaining,0),pay=debts.filter(x=>x.direction==='payable').reduce((s,x)=>s+x.remaining,0);const activeRep=recordsLive().filter(r=>['repair','rep'].includes(r.kind)&&!['delivered','done','cancelled','canceled'].includes(r.status)).length;const overdue=debts.filter(x=>x.dueDate&&x.dueDate<today()).length;const recent=all.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.time||'').localeCompare(a.time||'')).slice(0,6);const hasData=all.length>0;const actions=`${writable()?`<button class="btn btn-outline" data-action="new-deal">＋ ${esc(tr('صفقة جديدة'))}</button>`:''}${hasData&&settingsWrite()&&all.some(r=>r.isDemo)?`<button class="btn btn-outline" data-action="clear-demo">${esc(tr('مسح البيانات التجريبية'))}</button>`:''}`;return`${pageHeading('الرئيسية',role==='operator'?'ملخص السجلات التشغيلية':'ملخص حي للمبيعات والديون والخزينة',actions)}${hasData&&all.some(r=>r.isDemo)?`<div class="notice info" style="margin-bottom:12px">${esc(tr('تعرض هذه المساحة بيانات تجريبية قابلة للحذف.'))}</div>`:''}<div class="segmented" style="margin-bottom:13px;display:inline-flex">${[['month','هذا الشهر'],['today','اليوم'],['week','الأسبوع'],['year','هذا العام'],['all','كل الفترات']].map(([v,label])=>`<button class="${dashPeriod===v?'active':''}" data-action="period" data-period="${v}">${esc(tr(label))}</button>`).join('')}</div>${role==='operator'?`<div class="stat-grid"><div class="stat-tile"><span>${esc(tr('الصفقات'))}</span><strong>${deals.length}</strong></div><div class="stat-tile"><span>${esc(tr('تذاكر إصلاح نشطة'))}</span><strong>${activeRep}</strong></div><div class="stat-tile"><span>${esc(tr('الحيوانات المسجلة'))}</span><strong>${liveDocs('animals').length}</strong></div><div class="stat-tile"><span>${esc(tr('سجلات الأراضي'))}</span><strong>${liveDocs('lands').length}</strong></div><div class="stat-tile"><span>${esc(tr('أصناف الكتالوج'))}</span><strong>${liveDocs('catalog').length}</strong></div><div class="stat-tile"><span>${esc(tr('عدد السجلات'))}</span><strong>${periodRows.length}</strong></div></div>`:`<div class="stat-grid"><div class="stat-tile"><span>${esc(tr('الإيرادات'))}</span><strong>${money(revenue)}</strong></div><div class="stat-tile"><span>${esc(tr('التكاليف'))}</span><strong>${money(costs)}</strong></div><div class="stat-tile"><span>${esc(tr('صافي الربح'))}</span><strong class="${profit>=0?'amount-positive':'amount-negative'}">${money(profit)}</strong></div><div class="stat-tile"><span>${esc(tr('المطلوب تحصيله'))}</span><strong class="amount-positive">${money(rec)}</strong></div><div class="stat-tile"><span>${esc(tr('المطلوب سداده'))}</span><strong class="amount-negative">${money(pay)}</strong></div><div class="stat-tile"><span>${esc(tr('تذاكر إصلاح نشطة'))}</span><strong>${activeRep}</strong></div></div>`}<div class="content-grid" style="margin-top:14px"><div class="stack">${panel('آخر العمليات',recent.length?`<div class="list">${recent.map(r=>{const isDeal=['deal','buy'].includes(r.kind),isRepair=['repair','rep'].includes(r.kind),isVoucher=['voucher','vch'].includes(r.kind);const title=r.item||r.title||r.reason||tr('عملية');const amount=isDeal?num(r.sale??r.sell):isRepair?num(r.charge??r.price):isVoucher?num(r.amount??r.amt):num(r.total);return`<div class="list-row"><div class="row-icon">${isDeal?'↔':isRepair?'⌁':isVoucher?'▤':'◷'}</div><div class="row-main"><strong>${esc(title)}</strong><small>${esc(dtext(r.date,r.time))} · ${esc(r.ref||'')}</small></div><div class="row-value">${money(amount)}</div></div>`}).join('')}</div>`:emptyState('لا توجد بيانات بعد','ابدأ بإضافة صفقة أو سجل متخصص.','◫'))}${panel('مؤشرات الأداء',`<div class="metric-row"><span>${esc(tr('عدد السجلات'))}</span><strong>${all.length}</strong></div><div class="metric-row"><span>${esc(tr('الصفقات'))}</span><strong>${all.filter(r=>['deal','buy'].includes(r.kind)).length}</strong></div><div class="metric-row"><span>${esc(tr('متأخر'))}</span><strong>${overdue}</strong></div><div class="notice info" style="margin-top:10px">${esc(tr('الأرباح تقريرية بحسب ما سُجّل؛ ليست ضماناً لعائد أو بديلاً عن المحاسبة الرسمية.'))}</div>`)}</div><div class="stack">${panel('النسخ المحلي',`<div class="notice success">${esc(tr('بياناتك محفوظة على هذا الجهاز فقط.'))} ${esc(tr('لا توجد مزامنة أو حساب سحابي.'))}</div><div class="sync-details" style="margin:12px 0"><i class="dot green"></i><span>${esc(tr('التخزين المحلي'))}</span><strong>${esc(storageMode==='indexedDB'?'IndexedDB':'Local storage')}</strong></div><button class="btn btn-outline" data-action="backup">${esc(tr('تنزيل نسخة JSON'))}</button><button class="btn btn-outline" data-action="encrypted-backup" style="margin-inline-start:6px">${esc(tr('تنزيل نسخة مشفرة بكلمة مرور'))}</button></div>`)}${role==='operator'?panel('متابعة التشغيل',activeRep?`<div class="list">${recordsLive().filter(r=>['repair','rep'].includes(r.kind)&&!['delivered','done','cancelled','canceled'].includes(r.status)).slice(0,6).map(r=>`<div class="list-row"><div class="row-icon">⌁</div><div class="row-main"><strong>${esc(r.item||tr('إصلاح'))}</strong><small>${esc(r.customer||r.cn||'')} · ${esc(r.status||'')}</small></div><div class="row-value">${esc(r.dueDate||r.date||'')}</div></div>`).join('')}</div>`:emptyState('لا توجد مهام تشغيلية معلقة','ستظهر هنا تذاكر الإصلاح النشطة.','⌁')):panel('تذكيرات المتابعة',debts.length?`<div class="list">${debts.slice(0,5).map(d=>`<div class="list-row"><div class="row-icon">${d.direction==='receivable'?'↙':'↗'}</div><div class="row-main"><strong>${esc(d.person)} · ${esc(d.title)}</strong><small>${esc(d.dueDate||d.date||'')} · ${esc(tr(d.direction==='receivable'?'دين لي':'دين عليّ'))}</small></div><div class="row-value">${money(d.remaining)}</div></div>`).join('')}</div>`:emptyState('لا توجد ديون مفتوحة','تظهر هنا الأرصدة غير المسددة.','◷'))}</div></div>`}

function summaryPeriodFilter(period){dashPeriod=['all','today','week','month','year'].includes(period)?period:'month'}
function downloadBlob(filename,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function timestampName(){return new Date().toISOString().slice(0,10)}
function backupPayload(){return{format:'merchant-ledger-backup',version:6,createdAt:new Date().toISOString(),workspaceName:workspace?.name||'',data:JSON.parse(JSON.stringify(state))}}
function downloadJsonBackup(){downloadBlob(`merchant-ledger-${timestampName()}.json`,new Blob([JSON.stringify(backupPayload(),null,2)],{type:'application/json;charset=utf-8'}));toast(tr('تم تنزيل النسخة'),'success')}
function csvEscape(v){return'"'+String(v??'').replace(/"/g,'""')+'"'}
function exportCSV(){const head=['مرجع','نوع العملية','التاريخ','الوقت','طريقة الدفع','المورد','هاتف المورد','بريد المورد','الزبون','هاتف الزبون','بريد الزبون','السلعة / الخدمة','الكمية','النشاط','نوع السلعة','الشراء','البيع','المصروفات','صافي الربح','المدفوع','المقبوض','الاستحقاق','ملاحظات'];const rows=[head];for(const r of recordsLive()){const deal=['deal','buy'].includes(r.kind),rep=['repair','rep'].includes(r.kind),debt=r.kind==='debt',voucher=['voucher','vch'].includes(r.kind);const profit=deal?num(r.sale??r.sell)-num(r.purchase??r.buy)-num(r.expenses??r.exp):rep?num(r.charge??r.price)-num(r.parts)-num(r.labor??r.pay):voucher?(r.direction==='income'||r.vtype==='inc'?num(r.amount??r.amt):-num(r.amount??r.amt)):0;rows.push([r.ref||'',deal?tr('صفقة'):rep?tr('إصلاح'):debt?tr('دين مستقل'):voucher?tr(r.direction==='income'||r.vtype==='inc'?'سند قبض':'سند صرف'):r.kind||'',r.date||'',r.time||'',tr(r.method||''),r.supplier||r.sn||'',r.supplierPhone||r.sp||'',r.supplierEmail||r.se||'',r.customer||r.cn||'',r.customerPhone||r.cp||'',r.customerEmail||r.ce||'',r.item||r.title||r.reason||'',r.qty??'',r.activity?categoryName('activities',r.activity):'',r.goodType?categoryName('goods',r.goodType):'',deal?r.purchase??r.buy:rep?r.parts:debt&&r.direction==='payable'?r.total:'',deal?r.sale??r.sell:rep?r.charge??r.price:debt&&r.direction!=='payable'?r.total:'',deal?r.expenses??r.exp:rep?num(r.parts)+num(r.labor??r.pay):voucher&&r.direction!=='income'&&r.vtype!=='inc'?r.amount??r.amt:'',profit,r.paid??'',r.received??r.recv??'',r.dueDate||'',r.note||'']);}const csv='\ufeff'+rows.map(row=>row.map(csvEscape).join(',')).join('\r\n');downloadBlob(`merchant-ledger-${timestampName()}.csv`,new Blob([csv],{type:'text/csv;charset=utf-8'}));toast(tr('تم تصدير CSV'),'success')}
function openPasswordModal(mode='encrypt'){const encrypt=mode==='encrypt';$('#modal-root').innerHTML=`<div class="modal-card"><div class="modal-head"><div><h2>${esc(tr(encrypt?'تشفير النسخة':'فك تشفير النسخة'))}</h2><p>${esc(tr(encrypt?'كلمة المرور لا تُحفظ. خزّنها منفصلة؛ لن يمكن استعادة الملف دونها.':'أدخل كلمة المرور التي استُخدمت لحماية النسخة.'))}</p></div><button class="icon-button" type="button" data-action="modal-close">×</button></div><form data-form="backup-password" data-mode="${mode}"><div class="form-grid single"><label class="field"><span>${esc(tr('كلمة مرور النسخة'))}</span><input name="password" type="password" minlength="10" required autocomplete="new-password"></label>${encrypt?`<label class="field"><span>${esc(tr('تأكيد كلمة المرور'))}</span><input name="confirm" type="password" minlength="10" required autocomplete="new-password"></label>`:''}</div><div class="form-footer"><span class="form-note">${esc(tr('استخدم كلمة مرور فريدة لا تقل عن 10 أحرف.'))}</span><button class="btn btn-primary" type="submit">${esc(tr(encrypt?'تشفير النسخة':'فك التشفير'))}</button></div></form></div>`;$('#modal-root').hidden=false;$('#modal-root input')?.focus()}
function bytesToB64(bytes){let s='';const arr=new Uint8Array(bytes);for(let i=0;i<arr.length;i+=0x8000)s+=String.fromCharCode(...arr.subarray(i,i+0x8000));return btoa(s)}
function b64ToBytes(text){const s=atob(text);const out=new Uint8Array(s.length);for(let i=0;i<s.length;i++)out[i]=s.charCodeAt(i);return out}
async function backupKey(password,salt,iterations=310000){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encryptBackup(password){if(!crypto.subtle)throw new Error(tr('تعذر إنشاء النسخة المشفرة'));const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),iterations=310000,key=await backupKey(password,salt,iterations),plain=new TextEncoder().encode(JSON.stringify(backupPayload())),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);const obj={format:'merchant-ledger-encrypted',version:1,algorithm:'AES-GCM',kdf:'PBKDF2-SHA-256',iterations,salt:bytesToB64(salt),iv:bytesToB64(iv),ciphertext:bytesToB64(cipher)};downloadBlob(`merchant-ledger-encrypted-${timestampName()}.json`,new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));toast(tr('تم تنزيل النسخة المشفرة'),'success');return obj}
async function decryptBackup(obj,password){if(obj.format!=='merchant-ledger-encrypted'||obj.algorithm!=='AES-GCM'||obj.kdf!=='PBKDF2-SHA-256'||!Number.isInteger(obj.iterations)||obj.iterations<100000||obj.iterations>1000000)throw new Error(tr('النسخة المشفرة غير صالحة'));const key=await backupKey(password,b64ToBytes(obj.salt),obj.iterations),clear=await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(obj.iv)},key,b64ToBytes(obj.ciphertext));return JSON.parse(new TextDecoder().decode(clear))}
function mergeImportedState(incoming){let count=0;for(const k of COLLECTIONS){const map=new Map((state[k]||[]).map(x=>[String(x.id),x]));for(const doc of incoming[k]||[]){const id=String(doc.id);const old=map.get(id);if(!old){map.set(id,{...doc,id,_updatedAt:num(doc._updatedAt)||Date.now()});count++;continue}const same=JSON.stringify({...old,_updatedAt:0})===JSON.stringify({...doc,id,_updatedAt:0});if(!same&&num(doc._updatedAt)>num(old._updatedAt)){map.set(id,{...doc,id});count++}}state[k]=[...map.values()]}if(incoming.prefs&&num(incoming.prefs._updatedAt)>=num(state.prefs?._updatedAt)){state.prefs={...state.prefs,...incoming.prefs,shop:{...(state.prefs?.shop||{}),...(incoming.prefs.shop||{})}}}return count}
async function importBackupObject(obj,password=''){if(obj?.format==='merchant-ledger-encrypted')obj=await decryptBackup(obj,password);const incoming=normalizeImportedState(obj);if(!settingsWrite())throw new Error(tr('استيراد النسخ متاح للمالك أو المدير'));const count=mergeImportedState(incoming);if(!count&&!COLLECTIONS.some(k=>(incoming[k]||[]).length))throw new Error(tr('لا توجد بيانات صالحة للاستيراد'));await saveLocalState(false);render();scheduleSync();toast(`${tr('تم استيراد البيانات ودمجها')} · ${count}`,'success')}
async function handleImportFile(file){if(!file)return;if(!settingsWrite()){toast(tr('استيراد النسخ متاح للمالك أو المدير'),'error');return}try{let obj=JSON.parse(await file.text());if(obj?.format==='merchant-ledger-encrypted'){pendingImportObject=obj;openPasswordModal('decrypt');return}await importBackupObject(obj)}catch(e){toast(e.message||tr('تعذر استيراد الملف'),'error')}}
let pendingImportObject=null;
function printReceipt(recordId){const r=docById('records',recordId);if(!r){toast(tr('لا يوجد سجل مطابق'),'error');return}const shop=pref().shop||{},deal=['deal','buy'].includes(r.kind),repair=['repair','rep'].includes(r.kind),debt=r.kind==='debt',voucher=['voucher','vch'].includes(r.kind);const title=deal?'فاتورة / وصل':repair?'إيصال الإصلاح':debt?'كشف دين':voucher?tr(r.direction==='income'||r.vtype==='inc'?'سند قبض':'سند صرف'):'كشف داخلي';const gross=deal?num(r.sale??r.sell):repair?num(r.charge??r.price):debt?num(r.total):num(r.amount??r.amt);const paid=deal?num(r.received??r.recv):repair?num(r.received??r.recv):debt?num(r.paid):gross;const balance=Math.max(0,gross-paid);const name=r.customer||r.cn||r.person||r.party||r.supplier||r.sn||'—';const item=r.item||r.title||r.reason||tr('سجل');const lines=(r.payments||[]).map(p=>`<tr><td>${esc(dtext(p.date,p.time))}</td><td>${esc(tr(p.method||''))}</td><td>${esc(p.note||'')}</td><td>${money(p.amount??p.amt)}</td></tr>`).join('');const html=`<!doctype html><html lang="${uiLang}" dir="${uiLang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · ${esc(r.ref||'')}</title><style>*{box-sizing:border-box}body{font:15px system-ui,Arial,sans-serif;color:#1b302a;margin:0;padding:28px;background:#f5f7f4}.sheet{max-width:760px;margin:auto;background:#fff;border:1px solid #dce6df;border-radius:14px;padding:30px}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #226a50;padding-bottom:18px}.head h1{font-size:23px;margin:0 0 6px}.muted{color:#66776f;font-size:13px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:20px 0}.box{padding:12px;background:#f6f9f6;border-radius:9px}.box small{display:block;color:#74847c}.grid{width:100%;border-collapse:collapse;margin:16px 0}.grid td,.grid th{padding:9px 7px;border-bottom:1px solid #e2e9e4;text-align:start}.total{font-size:20px;font-weight:800;color:#176548}.note{margin-top:20px;padding:12px;border:1px solid #dce6df;border-radius:9px;font-size:12px;color:#65756e}.actions{display:flex;gap:8px;margin-bottom:15px}.actions button{border:0;background:#14604c;color:#fff;padding:9px 14px;border-radius:8px;font:inherit}@media print{body{background:#fff;padding:0}.sheet{border:0;border-radius:0;padding:0;max-width:none}.actions{display:none}}</style><body><main class="sheet"><div class="actions"><button onclick="window.print()">${esc(tr('طباعة / حفظ PDF'))}</button></div><header class="head"><div><h1>${esc(shop.name||tr('دفتر التاجر'))}</h1><div class="muted">${esc(shop.address||'')}</div><div class="muted">${esc(shop.phone||'')}</div></div><div style="text-align:end"><h2>${esc(tr(title))}</h2><div class="muted">${esc(r.ref||r.id)}</div></div></header><div class="meta"><div class="box"><small>${esc(tr('التاريخ'))} / ${esc(tr('الوقت'))}</small><strong>${esc(dtext(r.date,r.time))}</strong></div><div class="box"><small>${esc(tr('الزبون'))} / ${esc(tr('المورد'))}</small><strong>${esc(name)}</strong></div><div class="box"><small>${esc(tr('السلعة / الخدمة'))}</small><strong>${esc(item)}</strong></div><div class="box"><small>${esc(tr('طريقة الدفع'))}</small><strong>${esc(tr(r.method||'—'))}</strong></div></div><table class="grid"><tbody><tr><td>${esc(tr('المبلغ الإجمالي'))}</td><td>${money(gross)}</td></tr><tr><td>${esc(tr('المسدد'))}</td><td>${money(paid)}</td></tr><tr><td class="total">${esc(tr('الرصيد المتبقي'))}</td><td class="total">${money(balance)}</td></tr></tbody></table>${lines?`<h3>${esc(tr('الدفعات المسجلة'))}</h3><table class="grid"><thead><tr><th>${esc(tr('التاريخ'))}</th><th>${esc(tr('طريقة الدفع'))}</th><th>${esc(tr('ملاحظات'))}</th><th>${esc(tr('المبلغ'))}</th></tr></thead><tbody>${lines}</tbody></table>`:''}<div>${esc(r.note||r.fault||'')}</div><div class="note">${esc(tr('هذا المستند سجل داخلي وليس بديلاً عن فاتورة قانونية أو ضريبية.'))}</div></main><script>setTimeout(()=>window.print(),350)</script></body></html>`;const w=window.open('','_blank');if(!w){toast(tr('تعذر فتح نافذة الطباعة'),'error');return}w.opener=null;w.document.open();w.document.write(html);w.document.close()}
function openPaymentModal(id,side){const r=docById('records',id);if(!r||!canPayRecord(r)){toast(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'),'error');return}pendingPayment={id,side};let total=0,paid=0,person='';if(['deal','buy'].includes(r.kind)){if(side==='pay'){total=num(r.purchase??r.buy);paid=num(r.paid);person=r.supplier||r.sn||''}else{total=num(r.sale??r.sell);paid=num(r.received??r.recv);person=r.customer||r.cn||''}}else if(['repair','rep'].includes(r.kind)){total=num(r.charge??r.price);paid=num(r.received??r.recv);person=r.customer||r.cn||''}else{total=num(r.total);paid=num(r.paid);person=r.person||r.name||''}const remaining=Math.max(0,total-paid);$('#modal-root').innerHTML=`<div class="modal-card"><div class="modal-head"><div><h2>${esc(tr(side==='pay'?'تسديد':side==='receive'?'تحصيل':'تسجيل دفعة / قسط'))} · ${esc(person)}</h2><p>${esc(r.item||r.reason||r.ref||'')}</p></div><button class="icon-button" data-action="modal-close" type="button">×</button></div><form data-form="payment-modal"><div class="form-grid">${field('amount','المبلغ','number','',{required:true,min:.01,step:'any'})}${field('date','تاريخ الدفعة','date',today(),{required:true})}${field('time','الوقت','time',nowTime())}${selectField('method','طريقة الدفع',methodOptions(r.method||'نقداً'),r.method||'نقداً')}${field('note','تفاصيل الدفعة','text','',{full:true})}</div><div class="notice info" style="margin-top:11px">${esc(tr('المبلغ المتبقي'))}: ${money(remaining)}</div><div class="form-footer"><span class="form-note">${esc(tr('سجّل الدفعة الفعلية دون إضافة فوائد تأخير.'))}</span><button class="btn btn-primary" type="submit">${esc(tr('تأكيد الدفعة'))}</button></div></form></div>`;$('#modal-root').hidden=false;$('#modal-root input[name="amount"]')?.focus()}
function openPrivacyModal(){const msg=`${tr('بياناتك محفوظة على هذا الجهاز فقط.')} ${tr('لا توجد مزامنة أو حساب سحابي.')} ${tr('النسخ الاحتياطي اليدوي ضروري؛ مسح بيانات المتصفح قد يحذف سجلاتك.')} ${tr('لا تظهر البيانات تلقائياً على هاتف أو حاسوب آخر.')}`;$('#modal-root').innerHTML=`<div class="modal-card"><div class="modal-head"><div><h2>${esc(tr('الخصوصية'))}</h2><p>${esc(tr('تخزين محلي'))}</p></div><button class="icon-button" data-action="modal-close" type="button">×</button></div><div class="notice info">${esc(msg)}</div><p class="form-note">${esc(tr('تذكيرات واتساب تحتاج اتصالاً بالإنترنت عند إرسالها.'))}</p></div>`;$('#modal-root').hidden=false}
function closeModal(){$('#modal-root').hidden=true;$('#modal-root').innerHTML='';pendingPayment=null;if(pendingImportObject)pendingImportObject=null}
function scrollToForm(name){const f=document.querySelector(`[data-form="${name}"]`);if(f){f.scrollIntoView({behavior:'smooth',block:'center'});f.querySelector('input:not([type=hidden]),select')?.focus({preventScroll:true})}}
function toggleLanguage(){uiLang=uiLang==='ar'?'en':'ar';try{localStorage.setItem('ledger-language',uiLang)}catch(e){}if(workspace){state.prefs={...pref(),language:uiLang,_updatedAt:Date.now()};saveLocalState(false);applyLang();$('#workspace-name').textContent=state.prefs.shop?.name||tr('الدفتر المحلي');$('#workspace-role').textContent=tr('تخزين محلي');$('#user-name').textContent=tr('هذا الجهاز');$('#user-email').textContent=tr('بيانات محفوظة على هذا الجهاز');setSyncState('local',tr('محفوظ على هذا الجهاز'));render()}else applyLang()}
async function openWorkspaceModal(){const rows=workspaceList.map(w=>`<button class="role-row" type="button" data-action="switch-local-workspace" data-id="${esc(w.id)}" style="width:100%;background:#fff;border:0;text-align:start"><span><strong>${esc(w.name||tr('الدفتر المحلي'))}</strong><small class="form-note">${w.id===workspace?.id?esc(tr('الدفتر الحالي')):esc(tr('تخزين محلي'))}</small></span>${w.id===workspace?.id?'✓':'→'}</button>`).join('');$('#modal-root').innerHTML=`<div class="modal-card"><div class="modal-head"><div><h2>${esc(tr('دفاتر المتاجر على هذا الجهاز'))}</h2><p>${esc(tr('هذه الدفاتر منفصلة وتبقى على هذا الجهاز فقط.'))}</p></div><button class="icon-button" data-action="modal-close" type="button">×</button></div><div class="list">${rows}</div><form data-form="local-workspace" class="form-card" style="margin-top:14px"><h3>${esc(tr('إنشاء دفتر محلي'))}</h3><div class="form-grid">${field('name','اسم المتجر','text','',{required:true})}</div><div class="form-footer"><span class="form-note">${esc(tr('لا توجد مزامنة تلقائية بين الأجهزة.'))}</span><button class="btn btn-primary" type="submit">＋ ${esc(tr('إنشاء دفتر جديد'))}</button></div></form></div>`;$('#modal-root').hidden=false}
async function openLocalApp(targetId=''){
 let list=await localRead('local-workspaces');if(!Array.isArray(list))list=[];list=list.filter(x=>x&&typeof x.id==='string'&&x.id);
 if(!list.length){let oldState=await localRead('workspace:device-local');if(!oldState){const old=await localRead('auth-cache');if(old?.workspace?.id)oldState=await localRead(`workspace:${old.workspace.id}`)}if(!oldState)oldState=blankState();const seedName=oldState.prefs?.shop?.name||tr('الدفتر المحلي');list=[{id:'device-local',name:seedName}];await localWrite('workspace:device-local',oldState);await localWrite('local-workspaces',list)}
 const remembered=targetId||await localRead('active-local-workspace');let selected=list.find(w=>w.id===remembered)||list[0];if(!selected){selected={id:'device-local',name:tr('الدفتر المحلي')};list=[selected];await localWrite('local-workspaces',list)}
 workspaceList=list;const saved=await localRead(`workspace:${selected.id}`);state=roleScopedState(saved||blankState(),'owner');role='owner';const name=state.prefs?.shop?.name||selected.name||tr('الدفتر المحلي');workspace={...selected,name,role:'owner'};
 if(selected.name!==name){workspaceList=workspaceList.map(w=>w.id===selected.id?{...w,name}:w);await localWrite('local-workspaces',workspaceList)}await localWrite('active-local-workspace',selected.id);
 currentUser={id:'local-owner',name:tr('مستخدم هذا الجهاز'),email:''};teamMembers=[];applyPrefs();$('#auth-screen').hidden=true;$('#app-screen').hidden=false;$('#workspace-name').textContent=name;$('#workspace-role').textContent=tr('تخزين محلي');$('#user-name').textContent=tr('هذا الجهاز');$('#user-email').textContent=tr('بيانات محفوظة على هذا الجهاز');$('#profile-avatar').textContent='م';$('#profile-mini-letter').textContent='م';$('#logout-btn').hidden=true;const sw=$('#workspace-switcher');if(sw){sw.disabled=false;sw.setAttribute('aria-label',tr('دفاتر المتاجر على هذا الجهاز'))}$$('[data-page=team]').forEach(b=>b.hidden=true);$('#offline-banner').hidden=true;setSyncState('local',tr('محفوظ على هذا الجهاز'));await saveLocalState(false);render();
}
async function switchLocalWorkspace(id){if(!workspaceList.some(w=>w.id===id))return;await saveLocalState(false);await localWrite('active-local-workspace',id);closeModal();await openLocalApp(id);toast(tr('تم التبديل إلى الدفتر'),'success')}
async function createLocalWorkspace(o){const name=(o.name||'').trim().slice(0,100);if(!name)throw new Error(tr('اسم الدفتر مطلوب'));if(workspaceList.some(w=>(w.name||'').trim().toLowerCase()===name.toLowerCase()))throw new Error(tr('يوجد دفتر بهذا الاسم'));const id=uid('store'),data=blankState();data.prefs={...data.prefs,language:uiLang,shop:{...data.prefs.shop,name}};await localWrite(`workspace:${id}`,data);workspaceList=[...workspaceList,{id,name,role:'owner'}];await localWrite('local-workspaces',workspaceList);await switchLocalWorkspace(id);toast(tr('تم إنشاء دفتر محلي'),'success')}

