async function clearDemo(){if(!settingsWrite()||!(await askConfirm(tr('هل تريد حذف جميع السجلات التجريبية؟'))))return;let n=0;for(const c of COLLECTIONS)for(const x of state[c]||[])if(x.isDemo&&!x._deleted){tombstone(c,x.id);n++}await commit({message:'تم حذف البيانات التجريبية'});if(!n)toast(tr('لا توجد بيانات تجريبية'))}
function addNewRecord(page){if(!writable()&&['deals','repairs'].includes(page)){toast(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'),'error');return}editingId=null;editingAnimalId=null;editingLandId=null;editingCatalogId=null;currentPage=page;render();scrollToForm(({deals:'deal',repairs:'repair',debts:'debt',treasury:'voucher',livestock:'animal',lands:'land',catalog:'catalog'})[page])}
function assertMoney(o,key,label,allowBlank=true){const raw=o[key];if((raw===undefined||raw==='')&&allowBlank)return 0;const v=Number(raw);if(!Number.isFinite(v)||v<0)throw new Error(`${tr('أدخل مبلغاً صحيحاً')}: ${tr(label)}`);return v}
async function submitForm(form){const type=form.dataset.form;const o=Object.fromEntries(new FormData(form).entries());try{if(type==='deal')return await saveDeal(o);if(type==='repair')return await saveRepair(o);if(type==='debt')return await saveDebt(o);if(type==='voucher')return await saveVoucher(o);if(type==='animal')return await saveAnimal(o);if(type==='care')return await saveCare(o);if(type==='land')return await saveLand(o);if(type==='settings')return await saveSettings(o);if(type==='local-workspace')return await createLocalWorkspace(o);if(type==='category')return await saveCategory(o);if(type==='catalog')return await saveCatalog(o);if(type==='payment-modal')return await savePayment(o);if(type==='backup-password'){const password=o.password||'';if(form.dataset.mode==='encrypt'){if(password.length<10)throw new Error(tr('كلمة المرور يجب أن تكون 10 أحرف على الأقل'));if(password!==o.confirm)throw new Error(tr('كلمة المرور يجب أن تتطابق'));await encryptBackup(password);closeModal()}else{if(!pendingImportObject)throw new Error(tr('النسخة المشفرة غير صالحة'));const obj=pendingImportObject;pendingImportObject=null;await importBackupObject(obj,password);closeModal()}return}}catch(err){toast(err.message||tr('تعذر حفظ البيانات'),'error')}}
async function saveDeal(o){
  if(!writable())throw new Error(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'));
  const old=editingId?docById('records',editingId):null;
  const inventoryAuto=pref().inventoryMode==='auto';
  const catalogItem=inventoryAuto?docById('catalog',o.catalogItemId):null;
  if(inventoryAuto&&!catalogItem)throw new Error(tr('اختر صنفاً من الكتالوج'));
  const item=inventoryAuto?catalogItem.name:(o.item||'').trim();
  if(!item)throw new Error(tr('أدخل اسم السلعة / الخدمة'));
  const qty=assertMoney(o,'qty','الكمية');
  if(qty<=0)throw new Error(tr('يجب أن تكون الكمية أكبر من صفر'));
  const purchase=assertMoney(o,'purchase','الشراء'),sale=assertMoney(o,'sale','البيع'),expenses0=assertMoney(o,'expenses','المصروفات'),paid=assertMoney(o,'paid','المدفوع للمورد'),received=assertMoney(o,'received','المقبوض من الزبون');
  const expenseItems=(()=>{try{const a=JSON.parse(o.expenseItems||'[]');return Array.isArray(a)?a.filter(x=>x&&num(x.v)>0).map(x=>({k:String(x.k||'other').slice(0,30),l:String(x.l||'').slice(0,60),v:Math.round(num(x.v)*100)/100})):[]}catch(e){return[]}})();
  const rearing=(()=>{try{const r=JSON.parse(o.rearing||'null');return r&&typeof r==='object'?{days:num(r.days),feedDay:num(r.feedDay),vet:num(r.vet),careDay:num(r.careDay)}:null}catch(e){return null}})();
  const expenses=expenseItems.length?Math.round(expenseItems.reduce((s,x)=>s+x.v,0)*100)/100:expenses0;
  if(paid>purchase||received>sale)throw new Error(tr('المبلغ المدفوع لا يمكن أن يتجاوز الإجمالي'));
  let inventoryItemId=old?.inventoryItemId||'',inventoryMovement=old?.inventoryMovement||'none',inventoryDelta=num(old?.inventoryDelta||0);
  const stockPlan=new Map();
  if(inventoryAuto){
    const movement=o.inventoryMovement;
    if(!['in','out','none'].includes(movement))throw new Error(tr('اختر حركة المخزون'));
    if(old?.inventoryItemId&&num(old.inventoryDelta)){
      const prior=docById('catalog',old.inventoryItemId);
      if(prior)stockPlan.set(prior.id,num(prior.stock)-num(old.inventoryDelta));
    }
    inventoryDelta=movement==='in'?qty:movement==='out'?-qty:0;
    if(inventoryDelta){
      const available=stockPlan.has(catalogItem.id)?stockPlan.get(catalogItem.id):num(catalogItem.stock);
      if(inventoryDelta<0&&available<qty)throw new Error(`${tr('الكمية المتاحة لا تكفي')}: ${available} ${catalogItem.unit||''}`);
      stockPlan.set(catalogItem.id,available+inventoryDelta);
    }
    inventoryItemId=catalogItem.id;inventoryMovement=movement;
    for(const [id,stock] of stockPlan){if(stock< -1e-8)throw new Error(tr('تعديل الصفقة سيجعل المخزون سالباً؛ صحّح الكمية في الكتالوج أولاً.'));if(stock<0)stockPlan.set(id,0)}
  }else if(old?.inventoryItemId&&num(old.inventoryDelta)){
    if(qty!==num(old.qty)||item!==old.item)throw new Error(tr('هذا السجل مرتبط بحركة مخزون؛ فعّل التحديث التلقائي لتغيير الصنف أو الكمية.'));
  }
  const obj={kind:old?.kind||'deal',ref:old?.ref||`DL-${Date.now().toString(36).toUpperCase()}`,date:o.date||today(),time:o.time||nowTime(),item,qty,activity:o.activity||'',goodType:o.goodType||'',animalId:o.animalId||'',animalName:docById('animals',o.animalId||'')?.name||old?.animalName||'',supplier:(o.supplier||'').trim(),supplierPhone:(o.supplierPhone||'').trim(),customer:(o.customer||'').trim(),customerPhone:(o.customerPhone||'').trim(),purchase,sale,expenses,expenseItems,rearing,paid,received,method:o.method||'نقداً',dueDate:o.dueDate||'',customerDueDate:o.customerDueDate||'',note:(o.note||'').trim(),payments:Array.isArray(old?.payments)?old.payments:[],inventoryItemId,inventoryMovement,inventoryDelta};
  for(const [id,stock] of stockPlan){if(docById('catalog',id))updateDoc('catalog',id,{stock})}
  if(old)updateDoc('records',old.id,obj);else createDoc('records',obj);
  editingId=null;await commit({message:'تم حفظ التغييرات'})
}
