async function saveCatalog(o){if(!operationsWrite())throw new Error(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'));const name=(o.name||'').trim();if(!name)throw new Error(tr('أدخل اسم السلعة / الخدمة'));const cost=o.cost===''?'':assertMoney(o,'cost','تكلفة مرجعية'),price=o.price===''?'':assertMoney(o,'price','سعر بيع مرجعي'),stock=assertMoney(o,'stock','الكمية المسجلة'),minStock=assertMoney(o,'minStock','حد التنبيه');const obj={name,sku:(o.sku||'').trim(),category:o.category||'',unit:(o.unit||'وحدة').trim(),cost,price,stock,minStock,notes:(o.notes||'').trim()};if(editingCatalogId)updateDoc('catalog',editingCatalogId,obj);else createDoc('catalog',obj);editingCatalogId=null;await commit({message:'تم حفظ التغييرات'})}
async function saveSettings(o){if(!settingsWrite())throw new Error(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'));state.prefs={...pref(),currency:(o.currency||'د.م.').trim().slice(0,12),language:uiLang,inventoryMode:o.inventoryMode==='auto'?'auto':'manual',shop:{name:(o.shopName||'').trim(),phone:(o.shopPhone||'').trim(),address:(o.shopAddress||'').trim()},_updatedAt:Date.now()};const name=state.prefs.shop.name||tr('الدفتر المحلي');if(workspace){workspace.name=name;workspaceList=workspaceList.map(w=>w.id===workspace.id?{...w,name}:w);await localWrite('local-workspaces',workspaceList)}$('#workspace-name').textContent=name;await commit({message:'تم حفظ التغييرات'})}
async function saveCategory(o){if(!settingsWrite())throw new Error(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'));const type=o.type;if(!['activities','goods'].includes(type))return;const name=(o.name||'').trim().slice(0,80);if(!name)return;const exists=categoryDefs(state[type],type==='activities'?DEFAULT_ACTIVITIES:DEFAULT_GOODS).some(x=>x.name?.toLowerCase()===name.toLowerCase()||x.ar?.toLowerCase()===name.toLowerCase()||x.en?.toLowerCase()===name.toLowerCase());if(exists){toast(tr('هذا التصنيف موجود بالفعل'),'error');return}const bilingual=splitBilingual(name);createDoc(type,{name:bilingual.ar,ar:bilingual.ar,en:bilingual.en});await commit({message:'تمت إضافة التصنيف'})}
async function savePayment(o){if(!pendingPayment)return;const r=docById('records',pendingPayment.id);if(!r||!canPayRecord(r))throw new Error(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'));const amount=assertMoney(o,'amount','المبلغ',false);if(amount<=0)throw new Error(tr('أدخل مبلغاً صحيحاً'));let total=0,paid=0;if(['deal','buy'].includes(r.kind)){if(pendingPayment.side==='pay'){total=num(r.purchase??r.buy);paid=num(r.paid)}else{total=num(r.sale??r.sell);paid=num(r.received??r.recv)}}else if(['repair','rep'].includes(r.kind)){total=num(r.charge??r.price);paid=num(r.received??r.recv)}else{total=num(r.total);paid=num(r.paid)}if(amount>Math.max(0,total-paid)+.00001)throw new Error(tr('المبلغ يتجاوز الرصيد المتبقي'));const side=pendingPayment.side;const payments=[...(r.payments||[]),{amount,amt:amount,side:side==='pay'?'owe':side==='receive'?'due':(r.direction==='payable'||r.debtType==='owe'?'owe':'due'),date:o.date||today(),time:o.time||nowTime(),method:o.method||r.method||'نقداً',note:(o.note||'').trim()}];const patch={payments};if(side==='pay')patch.paid=paid+amount;else if(side==='receive')patch.received=paid+amount;else patch.paid=paid+amount;updateDoc('records',r.id,patch);closeModal();await commit({message:'تمت إضافة الدفعة'})}
function editRecord(id,kind){const r=docById('records',id);if(!r)return;const allowed=(kind==='deal'||kind==='repair')?writable():(kind==='debt'||kind==='voucher')?financeWrite():false;if(!allowed){toast(tr('ليس لديك صلاحية لتنفيذ هذا الإجراء'),'error');return}editingId=id;currentPage=kind==='deal'?'deals':kind==='repair'?'repairs':kind==='voucher'?'treasury':'debts';render();scrollToForm(kind==='deal'?'deal':kind==='repair'?'repair':kind==='voucher'?'voucher':'debt')}
async function removeRecord(id){const r=docById('records',id);if(!r||!financeWrite())return;if(!(await askConfirm(tr('هل تريد حذف هذا السجل؟'))))return;const product=r.inventoryItemId?docById('catalog',r.inventoryItemId):null,delta=num(r.inventoryDelta);if(product&&delta){const next=num(product.stock)-delta;if(next<0){toast(tr('لا يمكن حذف حركة الشراء لأن الكمية الحالية أقل منها؛ صحّح المخزون أولاً.'),'error');return}updateDoc('catalog',product.id,{stock:next})}tombstone('records',id);commit({message:'تم حذف السجل'})}
async function removeAnimal(id){if(!operationsWrite())return;const animal=docById('animals',id);if(!animal||!(await askConfirm(tr('هل تريد حذف هذا الحيوان وسجل متابعته؟'))))return;tombstone('animals',id);for(const ev of liveDocs('events').filter(x=>x.animalId===id))tombstone('events',ev.id);if(editingAnimalId===id)editingAnimalId=null;commit({message:'تم حذف السجل'})}
async function removeLand(id){if(!operationsWrite())return;if(!docById('lands',id)||!(await askConfirm(tr('هل تريد حذف هذا السجل؟'))))return;tombstone('lands',id);if(editingLandId===id)editingLandId=null;commit({message:'تم حذف السجل'})}
async function removeEvent(id){if(!operationsWrite())return;if(!(await askConfirm(tr('هل تريد حذف هذه المتابعة؟'))))return;tombstone('events',id);commit({message:'تم حذف المتابعة'})}
async function removeCatalog(id){if(!operationsWrite())return;if(!docById('catalog',id))return;if(recordsLive().some(r=>r.inventoryItemId===id&&num(r.inventoryDelta)!==0)){toast(tr('لا يمكن حذف صنف مرتبط بحركات مخزون؛ احذف حركاته أو صحّحها أولاً.'),'error');return}if(!(await askConfirm(tr('هل تريد حذف هذا الصنف؟'))))return;tombstone('catalog',id);if(editingCatalogId===id)editingCatalogId=null;commit({message:'تم حذف السجل'})}
async function removeCategory(type,id){if(!settingsWrite())return;const doc=docById(type,id);if(!doc||!(await askConfirm(tr('حذف هذا التصنيف؟ لا تتغير العمليات السابقة.'))))return;tombstone(type,id);commit({message:'تم حذف التصنيف'})}
function navigateWithQuery(){const q=$('#record-search');if(q){listQuery=q.value;const pos=q.selectionStart;render();const again=$('#record-search');if(again){again.focus();try{again.setSelectionRange(pos,pos)}catch(e){}}}}

document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(form){e.preventDefault();submitForm(form)}});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){listQuery=e.target.value;navigateWithQuery();return}if(e.target.closest('[data-form="deal"]')){const f=e.target.closest('form');const val=n=>Number(f.elements[n]?.value||0);const out=$('#deal-live-profit');if(out)out.textContent=money(val('sale')-val('purchase')-val('expenses'))}});
document.addEventListener('change',e=>{if(e.target.id==='import-file'){handleImportFile(e.target.files?.[0]);e.target.value='';return}});
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();navigate(page.dataset.page);return}if(e.target.closest('#auth-language')||e.target.closest('#language-toggle')){toggleLanguage();return}if(e.target.closest('#mobile-menu')||e.target.closest('#mobile-more')){$('#mobile-drawer').hidden=false;$('#drawer-backdrop').hidden=false;return}if(e.target.closest('#close-drawer')||e.target.closest('#drawer-backdrop')){closeDrawer();return}if(e.target.closest('#collapse-sidebar')){$('#sidebar').classList.toggle('collapsed');return}if(e.target.closest('#dismiss-banner')){e.target.closest('.trial-banner').hidden=true;return}if(e.target.closest('#workspace-switcher')){openWorkspaceModal();return}if(e.target.closest('#profile-menu')){navigate('settings');return}const tab=e.target.closest('[data-auth-tab]');if(tab){showAuth(tab.dataset.authTab);return}const a=e.target.closest('[data-action]');if(!a)return;const id=a.dataset.id,action=a.dataset.action;if(action==='modal-close'){closeModal();return}if(action==='switch-local-workspace'){switchLocalWorkspace(id);return}if(action==='sync'){syncNow();return}if(action==='backup'){downloadJsonBackup();return}if(action==='encrypted-backup'){openPasswordModal('encrypt');return}if(action==='csv'){exportCSV();return}if(action==='demo'){seedDemo();return}if(action==='clear-demo'){clearDemo();return}if(action==='period'){dashPeriod=a.dataset.period;render();return}if(action==='privacy'){openPrivacyModal();return}if(action==='new-deal'){addNewRecord('deals');return}if(action==='new-repair'){addNewRecord('repairs');return}if(action==='focus-debt'){addNewRecord('debts');return}if(action==='focus-voucher'){addNewRecord('treasury');return}if(action==='focus-animal'){addNewRecord('livestock');return}if(action==='focus-catalog'){addNewRecord('catalog');return}if(action==='focus-land'){addNewRecord('lands');return}if(action==='cancel-edit'){editingId=null;editingAnimalId=null;editingLandId=null;editingCatalogId=null;render();return}if(action==='edit'){editRecord(id,a.dataset.kind);return}if(action==='edit-animal'){if(!operationsWrite())return;editingAnimalId=id;currentPage='livestock';render();scrollToForm('animal');return}if(action==='edit-land'){if(!operationsWrite())return;editingLandId=id;currentPage='lands';render();scrollToForm('land');return}if(action==='edit-catalog'){if(!operationsWrite())return;editingCatalogId=id;currentPage='catalog';render();scrollToForm('catalog');return}if(action==='delete-catalog'){removeCatalog(id);return}if(action==='delete-record'){removeRecord(id);return}if(action==='delete-animal'){removeAnimal(id);return}if(action==='delete-land'){removeLand(id);return}if(action==='delete-event'){removeEvent(id);return}if(action==='delete-category'){removeCategory(a.dataset.type,id);return}if(action==='payment'){openPaymentModal(id,a.dataset.side);return}if(action==='invoice'){printReceipt(id);return}if(action==='statement'){openStatement(a.dataset.person||'',a.dataset.phone||'');return}if(action==='print-statement'){printStatement(a.dataset.person||'');return}if(action==='remind'){sendReminder(a);return}if(action==='filter'){pageFilter=a.dataset.filter||'all';render();return}});
async function boot(){try{await openLocalDB()}catch(e){localDB=null;storageMode='localStorage'}if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});await openLocalApp()}boot();
function personStatementRows(person){const key=String(person||'').trim().toLowerCase(),rows=[];for(const r of recordsLive()){const matches=(...values)=>values.some(v=>String(v||'').trim().toLowerCase()===key);const date=dtext(r.date,r.time);if(['deal','buy'].includes(r.kind)){if(matches(r.customer,r.cn)){const total=num(r.sale??r.sell),paid=num(r.received??r.recv);rows.push({record:r,type:'receivable',title:`${tr('بيع')}: ${r.item||tr('صفقة')}`,date,total,paid,remaining:Math.max(0,total-paid)})}if(matches(r.supplier,r.sn)){const total=num(r.purchase??r.buy),paid=num(r.paid);rows.push({record:r,type:'payable',title:`${tr('شراء')}: ${r.item||tr('صفقة')}`,date,total,paid,remaining:Math.max(0,total-paid)})}}else if(['repair','rep'].includes(r.kind)&&matches(r.customer,r.cn)){const total=num(r.charge??r.price),paid=num(r.received??r.recv);rows.push({record:r,type:'receivable',title:`${tr('إصلاح')}: ${r.item||''}`,date,total,paid,remaining:Math.max(0,total-paid)})}else if(r.kind==='debt'&&matches(r.person,r.name)){const total=num(r.total),paid=num(r.paid);rows.push({record:r,type:r.direction==='payable'||r.debtType==='owe'?'payable':'receivable',title:r.reason||tr('دين مستقل'),date,total,paid,remaining:Math.max(0,total-paid)})}else if(['voucher','vch'].includes(r.kind)&&matches(r.party,r.person)){const income=r.direction==='income'||r.vtype==='inc';const total=num(r.amount??r.amt);rows.push({record:r,type:income?'income':'expense',title:r.title||r.category||tr('سند'),date,total,paid:total,remaining:0})}}return rows.sort((a,b)=>(a.record.date||'').localeCompare(b.record.date||''))}
function openStatement(person,phone=''){const rows=personStatementRows(person),rec=rows.filter(x=>x.type==='receivable').reduce((s,x)=>s+x.remaining,0),pay=rows.filter(x=>x.type==='payable').reduce((s,x)=>s+x.remaining,0);$('#modal-root').innerHTML=`<div class="modal-card"><div class="modal-head"><div><h2>${esc(tr('كشف حساب'))} · ${esc(person)}</h2><p>${esc(phone||tr('كشف داخلي'))}</p></div><button class="icon-button" data-action="modal-close" type="button">×</button></div><div class="stat-grid"><div class="stat-tile"><span>${esc(tr('المطلوب تحصيله'))}</span><strong class="amount-positive">${money(rec)}</strong></div><div class="stat-tile"><span>${esc(tr('المطلوب سداده'))}</span><strong class="amount-negative">${money(pay)}</strong></div><div class="stat-tile"><span>${esc(tr('عدد العمليات'))}</span><strong>${rows.length}</strong></div></div><div class="toolbar-right" style="margin:12px 0"><button class="btn btn-outline" data-action="print-statement" data-person="${esc(person)}">${esc(tr('طباعة / حفظ PDF'))}</button></div><div class="list">${rows.map(x=>`<article class="record-card"><div class="record-top"><div><strong>${esc(x.title)}</strong><div class="record-meta">${esc(x.date)} · ${esc(x.record.ref||'')}</div></div>${badge(x.type==='receivable'?'دين لي':x.type==='payable'?'دين عليّ':x.type==='income'?'سند قبض':'سند صرف',x.type==='receivable'||x.type==='income'?'green':x.type==='payable'?'red':'gray')}</div><div class="record-grid"><div><span>${esc(tr('المبلغ الإجمالي'))}</span><strong>${money(x.total)}</strong></div><div><span>${esc(tr('المسدد'))}</span><strong>${money(x.paid)}</strong></div><div><span>${esc(tr('المتبقي'))}</span><strong>${money(x.remaining)}</strong></div><div><span>${esc(tr('استحقاق'))}</span><strong>${esc(x.record.dueDate||'—')}</strong></div></div><div class="toolbar-right"><button class="icon-action-sm" data-action="invoice" data-id="${esc(x.record.id)}">${esc(tr('فاتورة / وصل'))}</button>${x.remaining>0&&phone?`<button class="icon-action-sm" data-action="remind" data-id="${esc(x.record.id)}" data-phone="${esc(phone)}" data-person="${esc(person)}" data-amount="${x.remaining}">${esc(tr('تذكير واتساب'))}</button>`:''}</div></article>`).join('')||emptyState('لا توجد عمليات مطابقة','سوف تظهر العمليات المسجلة لهذا العميل أو المورد.','♙')}</div><div class="notice info" style="margin-top:12px">${esc(tr('كشف داخلي مبني على السجلات المسجلة، وليس كشفاً مصرفياً أو فاتورة ضريبية.'))}</div></div>`;$('#modal-root').hidden=false}
function printStatement(person){const rows=personStatementRows(person),rec=rows.filter(x=>x.type==='receivable').reduce((s,x)=>s+x.remaining,0),pay=rows.filter(x=>x.type==='payable').reduce((s,x)=>s+x.remaining,0),shop=pref().shop||'';const html=`<!doctype html><html lang="${uiLang}" dir="${uiLang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><title>${esc(tr('كشف حساب'))} · ${esc(person)}</title><style>body{font:14px system-ui,Arial;margin:25px;color:#18332a}.wrap{max-width:850px;margin:auto}h1{font-size:22px}.muted{color:#687970}table{width:100%;border-collapse:collapse;margin-top:15px}td,th{padding:8px;border-bottom:1px solid #dfe7e1;text-align:start}.totals{display:flex;gap:30px;margin:15px 0;font-weight:700}.actions{margin-bottom:14px}@media print{.actions{display:none}}</style><main class="wrap"><div class="actions"><button onclick="window.print()">${esc(tr('طباعة / حفظ PDF'))}</button></div><h1>${esc(shop.name||tr('دفتر التاجر'))} · ${esc(tr('كشف حساب'))}</h1><p>${esc(person)} · ${esc(new Date().toLocaleDateString(uiLang==='ar'?'ar-MA':'en-GB'))}</p><div class="totals"><span>${esc(tr('المطلوب تحصيله'))}: ${money(rec)}</span><span>${esc(tr('المطلوب سداده'))}: ${money(pay)}</span></div><table><thead><tr><th>${esc(tr('التاريخ'))}</th><th>${esc(tr('البيان'))}</th><th>${esc(tr('نوع العملية'))}</th><th>${esc(tr('المبلغ الإجمالي'))}</th><th>${esc(tr('المسدد'))}</th><th>${esc(tr('المتبقي'))}</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.record.date||'')}</td><td>${esc(x.title)} · ${esc(x.record.ref||'')}</td><td>${esc(tr(x.type==='receivable'?'دين لي':x.type==='payable'?'دين عليّ':x.type==='income'?'سند قبض':'سند صرف'))}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.remaining)}</td></tr>`).join('')}</tbody></table><p class="muted">${esc(tr('كشف داخلي مبني على السجلات المسجلة، وليس كشفاً مصرفياً أو فاتورة ضريبية.'))}</p></main><script>setTimeout(()=>window.print(),300)</script></html>`;const w=window.open('','_blank');if(!w){toast(tr('تعذر فتح نافذة الطباعة'),'error');return}w.opener=null;w.document.open();w.document.write(html);w.document.close()}
